def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Counters
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    for me, op in history:
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if op == 'C':
            op_c += 1
        else:
            op_d += 1

    # Recent window (last 10)
    w = history[-10:] if n >= 10 else history
    wc = 0
    wd = 0
    for _, o in w:
        if o == 'C':
            wc += 1
        else:
            wd += 1
    wlen = len(w)
    wrate = wc / wlen if wlen else 1.0

    # Detect opponent's recent defection streak (up to window length)
    streak_d = 0
    for _, o in reversed(history):
        if o == 'D':
            streak_d += 1
        else:
            break
    # Detect opponent's recent cooperation streak
    streak_c = 0
    for _, o in reversed(history):
        if o == 'C':
            streak_c += 1
        else:
            break

    last_me, last_op = history[-1]

    # Late-game exploitation of a pure cooperator
    if n >= 95 and op_d == 0:
        return 'D'
    if n >= 90 and op_d <= 2 and op_c >= n - 2:
        # occasionally defect in the last few rounds
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # If opponent has never defected, keep cooperating (except near end handled above)
    if op_d == 0:
        return 'C'

    # If opponent almost never cooperates, defect hard
    if op_c == 0:
        return 'D'

    # Very defection-heavy opponent: mostly defect, occasional probe
    if op_d >= 3 and op_d * 3 >= n * 2:
        # If we've been stuck in DD for a while, try one cooperative probe
        if streak_d >= 4 and last_me == 'D':
            if rng.random() < 0.35:
                return 'C'
        return 'D' if rng.random() < 0.9 else 'C'

    # Opponent just defected
    if last_op == 'D':
        # Long mutual defection — attempt repair with a cooperative probe
        if last_me == 'D' and streak_d >= 3:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Isolated / mild defection against otherwise cooperative opponent -> forgive quickly
        if wrate >= 0.7:
            # forgive most of the time, small retaliation
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if wrate >= 0.5:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        # Defection-heavy window: retaliate but probe occasionally
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just cooperated
    # If we defected last while opponent cooperated, return to cooperation quickly
    if last_me == 'D':
        return 'C'

    # Both cooperated last round or we already cooperate
    if wrate >= 0.6:
        # Preserve mutual cooperation
        return 'C'

    if wrate >= 0.4:
        # Moderate cooperation window: mostly cooperate, occasional exploitation
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # Low cooperation window but opponent just cooperated: offer cooperation
    return 'C'
